simpleaction.formula:
FIELD Authors := @UserName;
FIELD CDate := @Today;
FIELD DocAuthor := @Name([CN];@UserName);SELECT @All

code.formula:
FIELD A := (dcod1 + "---" + Def1):(dcod2 + "---" + Def2):(dcod3 + "---" + Def3):(dcod4 + "---" + Def4):(dcod5 + "---" + Def5):(dcod6 + "---" + Def6):(dcod7 + "---" + Def7):(dcod8 + "---" + Def8):(dcod9 + "---" + Def9):(dcod10 + "---" + Def10);
FIELD Location := @Member("---";A);
@If( Location <= 1; ""; @Subset(A;Location - 1))

lutype := "Notes":"NoCache";
ludb :="PHBSVR/PHB": "Current/Document.nsf";
luview := "Lookup1";
lucol:= 1;
lookup := @DbColumn(lutype;ludb;luview;lucol);
SelType := "SDS";
lucol2 := 2;
SelDesc := @DbLookup(lutype;ludb;luview;SelType;lucol2);
FIELD Type := @Trim(SelType);
Type;
FIELD DocTitle := @Trim(SelDesc);

lutype := "Notes":"NoCache";
ludb :="PHBSVR/PHB": "PanCen - IMS/PCDept.nsf";
luview := "Lookupdept";
lucol:= 1;
lookup := @DbColumn(lutype;ludb;luview;lucol);
SelDept := @Prompt([OkCancelList];"Document Type";"Select a type";null;lookup);
FIELD Dept_1 := @Trim(SelDept);Dept_1;
FIELD Dept_1 := @Trim(SelDept);
Dept_1

